package com.xiaoxiaoshuo.reader;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;import org.json.JSONObject;import java.util.*;
public class MainActivity extends Activity{
 private final int green=Color.rgb(49,88,71);private LinearLayout root,content,nav,hotBox;private Handler handler=new Handler();private TextView quoteView;private int quoteIndex=0;private LegacySourceStore.State sourceState;private final String[] quotes={"日子缓缓向前，喜欢的文字会在某一页等你。","愿你读过山河，也仍然相信人间灯火。","把生活调成喜欢的频道，慢一点也没有关系。","有些答案不在远方，在安静读完的一页里。","晚风会经过窗台，故事会替你收藏今天的疲惫。","愿每一次翻页，都比昨天多一点从容。","人间烟火最寻常，也最值得认真喜欢。","读书不是逃离生活，是给生活多一扇窗。","心里有光，平凡的日子也会慢慢发亮。","愿你有书可读，有路可走，也有人间可爱。"};private final String[] hotWords={"剑来","诡秘之主","庆余年","凡人修仙传","大奉打更人","雪中悍刀行","遮天","斗破苍穹"};
 @Override public void onCreate(Bundle b){super.onCreate(b);SourceMaintenance.schedule(this);SourceMaintenance.runIfDue(this);sourceState=LegacySourceStore.prepare(this,80);buildShell();showHome();}@Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
 private void buildShell(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(247,244,238));content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);nav.setPadding(dp(8),dp(5),dp(8),dp(6));nav.setBackgroundColor(Color.WHITE);root.addView(nav,new LinearLayout.LayoutParams(-1,dp(78)));setContentView(root);getWindow().setStatusBarColor(Color.rgb(247,244,238));getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);}
 private void renderNav(int active){nav.removeAllViews();String[] labels={"首页","发现","书架","我的"};String[] glyph={"⌂","✦","▣","●"};for(int i=0;i<4;i++){final int idx=i;boolean on=i==active;LinearLayout item=new LinearLayout(this);item.setOrientation(LinearLayout.VERTICAL);item.setGravity(Gravity.CENTER);TextView icon=tx(glyph[i],on?27:25,on?green:Color.rgb(105,105,101),true);icon.setGravity(Gravity.CENTER);TextView label=tx(labels[i],on?15:14,on?green:Color.rgb(92,92,88),true);label.setGravity(Gravity.CENTER);label.setPadding(0,dp(1),0,0);item.addView(icon,new LinearLayout.LayoutParams(-1,dp(34)));item.addView(label,new LinearLayout.LayoutParams(-1,dp(24)));item.setOnClickListener(x->{if(idx==0)showHome();else if(idx==1)showDiscover();else if(idx==2)showShelf();else showMe();});nav.addView(item,new LinearLayout.LayoutParams(0,-1,1));}}
 private ScrollView page(String title,String subtitle,int active){handler.removeCallbacksAndMessages(null);content.removeAllViews();renderNav(active);ScrollView sv=new ScrollView(this);sv.setFillViewport(true);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(18),dp(20),dp(34));box.addView(tx(title,28,green,true));TextView s=tx(subtitle,13,Color.rgb(126,118,107),false);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(4);sp.bottomMargin=dp(15);box.addView(s,sp);sv.addView(box);content.addView(sv,new LinearLayout.LayoutParams(-1,-1));return sv;}private LinearLayout body(ScrollView sv){return(LinearLayout)sv.getChildAt(0);}
 private void showHome(){ScrollView sv=page("小小说","把喜欢的故事，放进日常。",0);LinearLayout box=body(sv);box.addView(hero(),mp(0,0,0,14));box.addView(searchBar(),mp(0,0,0,7));box.addView(searchExtras(),mp(0,0,0,16));LinearLayout sec=new LinearLayout(this);sec.setGravity(Gravity.CENTER_VERTICAL);sec.setPadding(0,dp(4),0,dp(4));TextView ht=tx("热门小说",19,Color.rgb(45,60,52),true);sec.addView(ht,new LinearLayout.LayoutParams(0,-2,1));TextView more=tx("分类推荐 ›",13,green,true);sec.addView(more);View.OnClickListener openHot=v->startActivity(new Intent(this,HotCategoryActivity.class));sec.setOnClickListener(openHot);ht.setOnClickListener(openHot);more.setOnClickListener(openHot);box.addView(sec,mp(0,0,0,8));TextView rule=tx("首页展示已验证热门书；点击“热门小说”进入详细分类，每个分类每天只更新一次",12,Color.rgb(132,124,113),false);box.addView(rule,mp(0,0,0,10));hotBox=new LinearLayout(this);hotBox.setOrientation(LinearLayout.VERTICAL);TextView loading=tx("正在读取热门小说缓存…",14,Color.rgb(111,104,95),false);loading.setPadding(dp(8),dp(20),dp(8),dp(24));hotBox.addView(loading);box.addView(hotBox);loadHotBooks(hotBox);}
 private View searchExtras(){LinearLayout wrap=new LinearLayout(this);wrap.setOrientation(LinearLayout.VERTICAL);wrap.addView(tx("热门搜索",12,Color.rgb(116,111,103),true));HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);for(String s:hotWords)row.addView(searchChip(s,false));hs.addView(row);wrap.addView(hs,new LinearLayout.LayoutParams(-1,dp(42)));List<String> history=readSearchHistory();if(!history.isEmpty()){wrap.addView(tx("最近搜索",12,Color.rgb(116,111,103),true));HorizontalScrollView hh=new HorizontalScrollView(this);hh.setHorizontalScrollBarEnabled(false);LinearLayout hr=new LinearLayout(this);for(int i=0;i<Math.min(8,history.size());i++)hr.addView(searchChip(history.get(i),true));hh.addView(hr);wrap.addView(hh,new LinearLayout.LayoutParams(-1,dp(42)));}return wrap;}
 private TextView searchChip(String s,boolean history){TextView v=tx(s,12,green,false);v.setGravity(Gravity.CENTER);v.setPadding(dp(11),dp(5),dp(11),dp(5));GradientDrawable d=new GradientDrawable();d.setColor(history?Color.WHITE:Color.rgb(237,244,239));d.setCornerRadius(dp(15));if(history)d.setStroke(dp(1),Color.rgb(224,230,225));v.setBackground(d);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(31));p.setMargins(0,dp(5),dp(7),0);v.setLayoutParams(p);v.setOnClickListener(x->{Intent i=new Intent(this,SearchActivity.class);i.putExtra("query",s);startActivity(i);});return v;}
 private List<String> readSearchHistory(){String raw=getSharedPreferences("search_history",MODE_PRIVATE).getString("items","");ArrayList<String> out=new ArrayList<>();if(raw.length()>0)for(String x:raw.split("\\n"))if(x.trim().length()>0)out.add(x.trim());return out;}
 private void loadHotBooks(final LinearLayout target){HotBookLoader.load(this,books->runOnUiThread(()->{if(target!=hotBox||target.getWindowToken()==null)return;target.removeAllViews();if(books.isEmpty()){TextView e=tx("首页热门缓存暂为空，点击“热门小说”进入分类推荐，分类会按日缓存。",14,Color.rgb(111,104,95),false);e.setPadding(dp(8),dp(20),dp(8),dp(24));e.setOnClickListener(v->startActivity(new Intent(this,HotCategoryActivity.class)));target.addView(e);return;}for(LegacyDexBridge.BookResult b:books)target.addView(bookCard(b),mp(0,0,0,12));}));}
 private View hero(){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.HORIZONTAL);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(18),dp(16),dp(12),dp(14));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(22));card.setBackground(g);LinearLayout left=new LinearLayout(this);left.setOrientation(LinearLayout.VERTICAL);LinearLayout tags=new LinearLayout(this);tags.setOrientation(LinearLayout.HORIZONTAL);tags.addView(tag("文学"));tags.addView(tag("治愈"));tags.addView(tag("生活"));left.addView(tags);quoteView=tx(quotes[quoteIndex],19,Color.rgb(45,59,51),true);quoteView.setLineSpacing(dp(4),1f);quoteView.setPadding(0,dp(14),dp(8),dp(8));left.addView(quoteView);left.addView(tx("今日一句 · 每8秒轻轻换一句",11,Color.rgb(148,137,120),false));card.addView(left,new LinearLayout.LayoutParams(0,dp(156),1));LiteraryIllustrationView art=new LiteraryIllustrationView(this);card.addView(art,new LinearLayout.LayoutParams(dp(132),dp(156)));handler.postDelayed(new Runnable(){public void run(){if(quoteView==null||quoteView.getWindowToken()==null)return;quoteIndex=(quoteIndex+1)%quotes.length;quoteView.animate().alpha(0f).setDuration(180).withEndAction(()->{quoteView.setText(quotes[quoteIndex]);quoteView.animate().alpha(1f).setDuration(260).start();}).start();handler.postDelayed(this,8000);}},8000);return card;}
 private TextView tag(String s){TextView v=tx(s,11,green,true);v.setGravity(Gravity.CENTER);v.setPadding(dp(9),dp(5),dp(9),dp(5));GradientDrawable d=new GradientDrawable();d.setColor(Color.rgb(237,244,239));d.setCornerRadius(dp(12));v.setBackground(d);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.rightMargin=dp(6);v.setLayoutParams(p);return v;}
 private View searchBar(){LinearLayout outer=new LinearLayout(this);outer.setGravity(Gravity.CENTER_VERTICAL);outer.setPadding(dp(5),dp(5),dp(5),dp(5));GradientDrawable shell=new GradientDrawable();shell.setColor(Color.WHITE);shell.setCornerRadius(dp(24));shell.setStroke(dp(1),Color.rgb(224,232,226));outer.setBackground(shell);EditText e=new EditText(this);e.setSingleLine(true);e.setHint("搜索书名或作者");e.setHintTextColor(Color.rgb(152,148,140));e.setTextColor(Color.rgb(44,53,48));e.setTextSize(16);e.setPadding(dp(16),0,dp(8),0);e.setBackgroundColor(Color.TRANSPARENT);e.setImeOptions(EditorInfo.IME_ACTION_SEARCH);outer.addView(e,new LinearLayout.LayoutParams(0,dp(58),1));SearchIconView icon=new SearchIconView(this);icon.setContentDescription("搜索");View.OnClickListener run=v->{String q=e.getText().toString().trim();Intent i=new Intent(this,SearchActivity.class);if(q.length()>0)i.putExtra("query",q);startActivity(i);};icon.setOnClickListener(run);e.setOnEditorActionListener((v,id,event)->{if(id==EditorInfo.IME_ACTION_SEARCH){run.onClick(v);return true;}return false;});LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(dp(62),dp(62));ip.gravity=Gravity.CENTER_VERTICAL;outer.addView(icon,ip);return outer;}
 private void showDiscover(){ScrollView sv=page("发现","从优质书源发现完整可读的小说。",1);LinearLayout box=body(sv);box.addView(iconCard("＋","添加更多书源","支持JSON、JSON数组和订阅网址",v->startActivity(new Intent(this,SourceManagerActivity.class))),mp(0,0,0,12));box.addView(iconCard("⌕","搜索全书源","按真实章节数排序搜索结果",v->startActivity(new Intent(this,SearchActivity.class))),mp(0,0,0,12));box.addView(iconCard("★","热门分类","24个细分类 · 每日缓存更新",v->startActivity(new Intent(this,HotCategoryActivity.class))),mp(0,0,0,18));}
 private void showShelf(){ScrollView sv=page("书架","打开书籍后自动下载全本；移除书籍时离线文件一起删除。",2);LinearLayout box=body(sv);box.addView(iconCard("＋","添加更多","搜索并把喜欢的书加入书架",v->startActivity(new Intent(this,SearchActivity.class))),mp(0,0,0,14));int count=0;Set<String> keys=new LinkedHashSet<>(getSharedPreferences("native_shelf",MODE_PRIVATE).getStringSet("keys",Collections.emptySet()));for(String key:keys){String raw=getSharedPreferences("native_shelf",MODE_PRIVATE).getString(key,"");try{JSONObject o=new JSONObject(raw);box.addView(shelfBookCard(o,key),mp(0,0,0,12));count++;}catch(Throwable ignored){}}if(count==0){ArrayList<LegacySourceStore.BookInfo> legacy=LegacySourceStore.loadLegacyBooks(this,50);for(LegacySourceStore.BookInfo b:legacy){box.addView(bookCard(b.title,b.author,b.intro,b.cover),mp(0,0,0,12));count++;}}if(count==0){TextView empty=tx("书架还是空的。点击“添加更多”搜索一本书。",15,Color.rgb(110,103,94),false);empty.setPadding(dp(10),dp(24),dp(10),dp(24));box.addView(empty);}}
 private View shelfBookCard(JSONObject o,String key){String title=o.optString("title"),author=o.optString("author"),intro=o.optString("intro"),cover=o.optString("cover"),bookUrl=o.optString("book_url"),sourceUrl=o.optString("source_url"),sourceJson=o.optString("source_json");LinearLayout wrap=new LinearLayout(this);wrap.setOrientation(LinearLayout.VERTICAL);wrap.addView(bookCard(title,author,intro,cover));TextView del=tx("移除书籍并删除离线缓存",12,Color.rgb(160,82,72),true);del.setGravity(Gravity.RIGHT);del.setPadding(dp(8),dp(10),dp(8),dp(4));del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("移除《"+title+"》？").setMessage("会同时删除这本书的本机目录、已缓存章节正文和封面。其他书籍不受影响。").setNegativeButton("取消",null).setPositiveButton("移除",(d,w)->{SharedPreferences p=getSharedPreferences("native_shelf",MODE_PRIVATE);LinkedHashSet<String> ks=new LinkedHashSet<>(p.getStringSet("keys",Collections.emptySet()));ks.remove(key);p.edit().remove(key).putStringSet("keys",ks).apply();OfflineBookCache.deleteBook(this,title,cover,bookUrl.length()>0?bookUrl:sourceUrl,sourceJson);Toast.makeText(this,"已移除并清理缓存",Toast.LENGTH_SHORT).show();showShelf();}).show());wrap.addView(del);return wrap;}
 private void showMe(){ScrollView sv=page("我的","常用功能全部图标化，一眼就能找到。",3);LinearLayout box=body(sv);sourceState=LegacySourceStore.prepare(this,80);SharedPreferences sm=getSharedPreferences("source_maintenance",MODE_PRIVATE);long last=sm.getLong("last_run",0L);String sync=last==0?"待首次自动同步":"已开启每日自动更新";TextView stat=tx("书源 "+sourceState.all.size()+" 个 · 智能启用 "+sourceState.selected.size()+" 个 · "+sync,13,green,true);stat.setPadding(dp(2),0,0,dp(12));box.addView(stat);LinearLayout r1=new LinearLayout(this);r1.addView(iconCard("◫","书源管理","添加 · 优选80 · 每日更新",v->startActivity(new Intent(this,SourceManagerActivity.class))),grid());r1.addView(iconCard("⚙","设置","阅读与兼容",v->openInfo("settings")),grid());box.addView(r1);LinearLayout r2=new LinearLayout(this);r2.addView(iconCard("?","帮助中心","搜索 · 目录 · 封面",v->openInfo("help")),grid());r2.addView(iconCard("§","免责声明","书源与内容说明",v->openInfo("disclaimer")),grid());box.addView(r2);TextView ver=tx("小小说 10.0.9 · 华为兼容原生架构",12,Color.rgb(145,138,128),false);ver.setGravity(Gravity.CENTER);ver.setPadding(0,dp(22),0,dp(10));box.addView(ver);}private void openInfo(String mode){Intent i=new Intent(this,InfoActivity.class);i.putExtra("mode",mode);startActivity(i);}
 private View bookCard(LegacyDexBridge.BookResult b){LinearLayout c=(LinearLayout)bookCard(b.title,b.author,b.intro,b.coverUrl);c.setOnClickListener(v->{Intent x=new Intent(this,BookDetailActivity.class);x.putExtra("title",b.title);x.putExtra("author",b.author);x.putExtra("intro",b.intro);x.putExtra("cover",b.coverUrl);x.putExtra("book_url",b.bookUrl);x.putExtra("source_name",b.sourceName);x.putExtra("source_url",b.sourceUrl);x.putExtra("source_json",b.sourceJson);startActivity(x);});return c;}
 private View bookCard(String title,String author,String intro,String coverUrl){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.HORIZONTAL);c.setPadding(dp(12),dp(12),dp(12),dp(12));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(18));c.setBackground(g);ImageView cover=new ImageView(this);cover.setImageDrawable(new LiteraryCoverDrawable(title));c.addView(cover,new LinearLayout.LayoutParams(dp(88),dp(124)));CoverLoader.load(cover,coverUrl,"","",title);LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(14),0,0,0);info.addView(tx(title,18,Color.rgb(39,49,44),true));TextView a=tx(author.length()>0?author:"作者待获取",12,Color.rgb(127,119,108),false);a.setPadding(0,dp(4),0,dp(8));info.addView(a);TextView i=tx(intro.length()>0?AiTypesetter.compactIntro(intro):"点击查看完整简介和章节目录",13,Color.rgb(82,80,75),false);i.setMaxLines(3);info.addView(i);TextView hint=tx("查看目录 · 更多章节 ›",12,green,true);hint.setGravity(Gravity.RIGHT|Gravity.BOTTOM);info.addView(hint,new LinearLayout.LayoutParams(-1,0,1));c.addView(info,new LinearLayout.LayoutParams(0,dp(124),1));c.setOnClickListener(v->{Intent x=new Intent(this,BookDetailActivity.class);x.putExtra("title",title);x.putExtra("author",author);x.putExtra("intro",intro);x.putExtra("cover",coverUrl);startActivity(x);});return c;}
 private LinearLayout iconCard(String icon,String title,String sub,View.OnClickListener l){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(14),dp(16),dp(14));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(18));c.setBackground(g);TextView ic=tx(icon,24,green,true);ic.setGravity(Gravity.CENTER);GradientDrawable ib=new GradientDrawable();ib.setColor(Color.rgb(237,244,239));ib.setCornerRadius(dp(18));ic.setBackground(ib);c.addView(ic,new LinearLayout.LayoutParams(dp(42),dp(42)));TextView t=tx(title,16,Color.rgb(46,57,51),true);t.setPadding(0,dp(10),0,dp(4));c.addView(t);c.addView(tx(sub,12,Color.rgb(127,119,108),false));c.setOnClickListener(l);return c;}private LinearLayout.LayoutParams grid(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(132),1);p.setMargins(dp(4),dp(4),dp(4),dp(4));return p;}private TextView tx(String s,int z,int color,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(color);v.setTypeface(Typeface.create("sans",b?Typeface.BOLD:Typeface.NORMAL));return v;}private LinearLayout.LayoutParams mp(int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}private int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
}
